import { toast } from "../host/toast.js";
import { markdownToReadableText } from "./markdown-readable-text.js";
import { removeThinkingContent } from "./markdown-copy-html.js";
const CONTENT_EXPORT_FORMATS = [
  { format: "pdf", label: "PDF" },
  { format: "docx", label: "Word" },
  { format: "html", label: "HTML" },
  { format: "markdown", label: "Markdown file" },
  { format: "text", label: "Text file" }
];
function fileBase(title) {
  const base = (title ?? "").replace(/[\\/:*?"<>|\u0000-\u001f]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 120);
  return base || "document";
}
function save(name, bytes, mime) {
  const url = URL.createObjectURL(new Blob([bytes], { type: mime }));
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  link.rel = "noopener";
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 3e4);
}
const DONE = {
  pdf: "PDF downloaded",
  docx: "Word document downloaded",
  html: "HTML page downloaded",
  markdown: "Markdown file downloaded",
  text: "Text file downloaded"
};
async function exportContent(markdown, format, title) {
  const source = removeThinkingContent(markdown);
  const name = fileBase(title);
  try {
    if (format === "markdown") save(`${name}.md`, source, "text/markdown;charset=utf-8");
    else if (format === "text") save(`${name}.txt`, markdownToReadableText(source), "text/plain;charset=utf-8");
    else {
      const { exportDocument } = await import("@ai-matrx/print/document");
      const exp = await exportDocument(source, format, { fileName: name });
      save(exp.fileName, exp.bytes, exp.mime);
    }
    toast.success(DONE[format]);
  } catch (error) {
    toast.error(`Export failed: ${error instanceof Error ? error.message : String(error)}`);
  }
}
async function printContent(markdown, title) {
  try {
    const { printMessage } = await import("./print-message.js");
    const outcome = await printMessage(removeThinkingContent(markdown), {
      title: title || "Document",
      skin: "document",
      onNotice: (level, message) => level === "warning" ? toast.warning(message) : toast.info(message)
    });
    if (outcome === "downloaded") toast.info("Pop-ups are blocked, so the print page downloaded as an HTML file.");
  } catch (error) {
    toast.error(`Print failed: ${error instanceof Error ? error.message : String(error)}`);
  }
}
export {
  CONTENT_EXPORT_FORMATS,
  exportContent,
  printContent
};
