import { WandSparkles } from "lucide-react";
import { getAction, registerAction } from "./provider.js";
import { hasExportPalette, openExportPalette } from "../../copy/ExportPalette.js";
const EXPORT_PALETTE_ACTION_ID = "export-palette";
const EXPORT_PALETTE_ACTION = {
  id: EXPORT_PALETTE_ACTION_ID,
  // THE Alchemy palette (transforms, formatted, JSON, every format, send to…) — one ⋯ entry (Arman, 2026-10-08).
  label: "Alchemy\u2026",
  icon: WandSparkles,
  category: "export",
  supportedSources: "*",
  renderSlot: "overflow",
  order: 0,
  visible: (ctx) => hasExportPalette(ctx.instanceKey("alchemy")),
  run: (ctx) => {
    openExportPalette(ctx.instanceKey("alchemy"));
  }
};
function ensureExportPaletteAction() {
  if (getAction(EXPORT_PALETTE_ACTION_ID)) return;
  registerAction(EXPORT_PALETTE_ACTION);
}
export {
  EXPORT_PALETTE_ACTION,
  EXPORT_PALETTE_ACTION_ID,
  ensureExportPaletteAction
};
